import test from 'node:test';import assert from 'node:assert/strict';
import {create,validate,reduce,model,markdown} from './state.js';
import {createHistory,commit,undo} from '../workshop-kit/state.js';
const edit=(w,id,field,value)=>reduce(w,{type:'option',id,field,value});
test('legacy arrows migrate as blank suggested hypotheses without inventing causal attachment or evidence',()=>{const old=create();delete old.links;delete old.compareIds;delete old.decision;for(const o of old.options){for(const k of ['linkId','expected','competing','observe','changed','reason','checked','ancestry'])delete o[k];}const w=validate(old);assert.equal(w.links.length,3);assert.ok(w.links.every(l=>l.origin==='sequence'&&l.mechanism===''&&l.status==='untested'));assert.ok(w.options.every(o=>o.linkId===null));assert.equal(w.options[1].why,old.options[1].why);assert.deepEqual(model.parse(model.serialize(w)),w);});
test('explicit directed links survive step reordering and allow feedback but reject duplicates and self links atomically',()=>{let w=create();const links=structuredClone(w.links);w=reduce(w,{type:'reorder-step',id:w.steps[0].id,direction:1});assert.deepEqual(w.links,links);w=reduce(w,{type:'add-link',id:'feedback',from:links[0].to,to:links[0].from});assert.equal(w.links.length,4);const before=structuredClone(w);assert.throws(()=>reduce(w,{type:'add-link',id:'duplicate',from:links[0].from,to:links[0].to}),/already/);assert.throws(()=>reduce(w,{type:'add-link',id:'self',from:links[0].from,to:links[0].from}));assert.deepEqual(w,before);});
test('editing the effect endpoint flags attached intervention and relationship while retaining reviewed source and observations',()=>{let w=create(),o=w.options[0],l=w.links[0];w=reduce(w,{type:'reviewed',id:o.id});w=reduce(w,{type:'link',id:l.id,field:'observations',value:'Three requests waited a week.'});w=reduce(w,{type:'link-status',id:l.id,value:'supporting'});w=reduce(w,{type:'review-link',id:l.id});const oSource=structuredClone(w.options[0].checked),lSource=structuredClone(w.links[0].checked);w=reduce(w,{type:'step',id:l.to,field:'mechanism',value:'An entirely different event.'});assert.ok(w.options[0].review);assert.ok(w.links[0].review);assert.deepEqual(w.options[0].checked,oSource);assert.deepEqual(w.links[0].checked,lSource);assert.equal(w.links[0].observations,'Three requests waited a week.');assert.equal(w.links[0].status,'supporting');});
test('changing conditions or test expectations invalidates context review; re-review captures current words',()=>{let w=create(),id=w.options[0].id;w=reduce(w,{type:'reviewed',id});w=reduce(w,{type:'link',id:w.links[0].id,field:'conditions',value:'Only reversible decisions.'});assert.ok(w.options[0].review);w=reduce(w,{type:'reviewed',id});assert.equal(w.options[0].review,false);w=edit(w,id,'expected','Less time waiting, same rework.');assert.ok(w.options[0].review);w=reduce(w,{type:'reviewed',id});assert.ok(w.options[0].checked.fields.some(f=>f.label==='expected'&&f.text==='Less time waiting, same rework.'));});
test('retargeting retains words and steps cannot be removed while referenced',()=>{let w=create(),o=w.options[0];w=edit(w,o.id,'competing','A quieter week.');w=reduce(w,{type:'target',id:o.id,value:w.links[2].id});assert.equal(w.options[0].competing,'A quieter week.');assert.equal(w.options[0].anchor,w.links[2].from);assert.ok(w.options[0].review);assert.throws(()=>reduce(w,{type:'remove-link',id:w.links[2].id}),/Retarget/);assert.throws(()=>reduce(w,{type:'remove-step',id:w.links[2].to}),/relationships/);w=reduce(w,{type:'target',id:o.id,value:''});assert.equal(w.options[0].linkId,null);});
test('branches preserve flat sources, independent tests and parent guards through portable work',()=>{let w=create(),id=w.options[0].id;w=edit(w,id,'test','Two weeks with a matched request mix.');w=reduce(w,{type:'branch',id,newId:'child'});const frozen=structuredClone(w.options.at(-1).ancestry);w=edit(w,id,'test','A different test.');assert.deepEqual(w.options.at(-1).ancestry,frozen);assert.equal(w.options.at(-1).test,'Two weeks with a matched request mix.');w=edit(w,'child','reason','Test a lower effort version.');w=reduce(w,{type:'branch',id:'child',newId:'grandchild'});assert.equal(w.options.at(-1).ancestry.parents.length,1);assert.ok(!JSON.stringify(w.options.at(-1).ancestry).includes('Parent snapshot'));assert.throws(()=>reduce(w,{type:'remove-option',id}),/parent/);assert.deepEqual(model.parse(model.serialize(w)),w);const md=markdown(w);assert.ok(md.includes('A quieter week.')===false);assert.ok(md.includes('Test a lower effort version.'));assert.ok(md.includes('Two weeks with a matched request mix.'));});
test('comparison limit, malformed relationship imports and ancestry cycles reject without losing existing choices',()=>{let w=create(),id=w.options[0].id;w=reduce(w,{type:'branch',id,newId:'four'});w=reduce(w,{type:'compare',id:'four'});w=reduce(w,{type:'branch',id,newId:'five'});const before=structuredClone(w);assert.throws(()=>reduce(w,{type:'compare',id:'five'}));assert.deepEqual(w,before);for(const mutation of [x=>x.options[0].linkId='missing',x=>x.links[0].to='missing',x=>x.links=null,x=>x.compareIds=['missing'],x=>x.options[0].ancestry={version:1,parked:false,parents:[{id,title:'self',fields:[]}]}]){const bad=structuredClone(w);mutation(bad);assert.throws(()=>validate(bad));}assert.deepEqual(w,before);});
test('choosing and retargeting can be undone and chosen test, comparison and decision export together',()=>{const initial=model.initial();let next=model.transition(initial,{type:'choose',id:initial.workspaces[0].options[0].id});let h=commit(createHistory(initial),next);next=model.transition(next,{type:'target',id:next.workspaces[0].options[0].id,value:next.workspaces[0].links[2].id});h=commit(h,next);assert.deepEqual(undo(h).present.workspaces[0].options[0].linkId,initial.workspaces[0].options[0].linkId);const w=reduce(next.workspaces[0],{type:'decision',value:'Compare waiting time and rework before widening the rule.'});const md=markdown(w);assert.match(md,/chosen for a test/);assert.match(md,/Included in comparison/);assert.match(md,/Compare waiting time and rework/);assert.deepEqual(model.parse(model.serialize(w)),w);});
test('long source wording and multibyte text remain portable when branching',()=>{let w=create();w=reduce(w,{type:'step',id:w.steps[0].id,field:'name',value:'長'.repeat(20000)});w=reduce(w,{type:'step',id:w.steps[1].id,field:'name',value:'短'.repeat(20000)});w=edit(w,w.options[0].id,'title','原'.repeat(20000));w=reduce(w,{type:'reviewed',id:w.options[0].id});w=reduce(w,{type:'branch',id:w.options[0].id,newId:'unicode'});assert.equal(w.options.at(-1).ancestry.parents[0].title.length,20000);assert.deepEqual(model.parse(model.serialize(w)),w);});
